# ===========================================================================
# PUPCore.ps1 — shared engine + PUP definitions for PUPRemover.
#
# Dot-source this file (or embed it via build.ps1). It only DEFINES
# $PupDefinitions and the Invoke-PUPScan / Invoke-PUPRemoval / reporting
# functions — it performs no scanning or removal on its own. The front-ends
# (PUPRemover-S1.ps1, PUPRemover-Test.ps1) drive it.
#
# Detection targets: WaveBrowser (+ sibling WebNavigatorBrowser), Blazer,
# Shift Browser, and ACE AI Browser (+ its AceLauncher dock). (Crystal PDF was
# intentionally dropped — it's an infostealer that SentinelOne already detects
# and kills, so it doesn't belong here.)
#
# Matching philosophy: MatchPattern is the single source of truth for "does
# this string belong to the PUP" and is applied to scheduled-task blobs,
# registry names/values, uninstall entries, installer filenames, process
# paths, and shortcut targets. Patterns are deliberately narrow so legitimate
# software never matches (Waves MaxxAudio, Wavebox, Siemens WinCC
# WebNavigator, BlazeRush, Trailblazer, redshift/openshift/ShiftN, Teams
# Shifts, and — for 'ace' — Microsoft.ACE.OLEDB / Access Database Engine,
# Acer, Surface, ACEStream, AceReader, ...). Folder names are matched EXACTLY
# under known roots — no wildcards touch the filesystem.
# ===========================================================================

$ErrorActionPreference = 'SilentlyContinue'

$script:PupDefinitions = @(
    @{
        # WaveBrowser ships with an Omaha-fork updater ("Wavesor SWUpdater")
        # that reinstalls it via per-SID scheduled tasks, and is commonly
        # co-installed with its sibling PUP WebNavigatorBrowser (same
        # Wavesor/Polarity lineage) — both are covered here.
        Name             = 'WaveBrowser'
        # 'webnavigator' MUST keep its 'browser' suffix requirement: bare
        # 'webnavigator' matches Siemens SIMATIC WinCC WebNavigator (SCADA).
        ProcessPattern   = '(?i)^(wavebrowser|webnavigatorbrowser)'
        MatchPattern     = '(?i)(?<![a-z])wave[\s_-]*browser|wavesor|swupdatertaskuser|webnavigator[\s_-]*browser|wavebrws'
        FolderNames      = @('WaveBrowser', 'Wavesor Software', 'WaveSor', 'WebNavigatorBrowser')
        ProfileRootFolderNames = @('WaveBrowser', 'Wavesor Software', 'WaveSor', 'WebNavigatorBrowser')
        MachineFolders   = @("$env:ProgramFiles\Wavesor", "${env:ProgramFiles(x86)}\Wavesor")
        RegistrySubKeys  = @(
            'Software\WaveBrowser',
            'Software\Wavesor',
            'Software\WebNavigatorBrowser',
            'Software\Microsoft\Windows\CurrentVersion\App Paths\wavebrowser.exe',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\WaveBrowser',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\WebNavigatorBrowser',
            'Software\Classes\CLSID\{9CD78CBC-FD21-4FFF-B452-9D792A58B7C4}'  # SWUpdater COM class
        )
        MachineRegistryKeys = @(
            'HKLM:\SOFTWARE\Wavesor',
            'HKLM:\SOFTWARE\WOW6432Node\Wavesor',
            'HKLM:\SOFTWARE\Policies\Wavesor'
        )
    },
    @{
        # PUP.Optional.BlazerBrowser (Malwarebytes). Chromium PUP browser;
        # its browser process is new_blazer.exe / new_blazer_proxy.exe, its
        # updater blazer_updater.exe runs via the BlazerBrowserUpdateTask
        # scheduled task. MatchPattern never matches a standalone 'Blazer'
        # word — a user's own C:\Users\<x>\Blazer folder, 'Chevy Blazer'
        # shortcuts, trailblazer gems and BlazeRush all stay untouched.
        # It requires browser context ('blazer...browser'), an attested
        # compound (blazer_updater / blazer_installer / blazer.exe), or the
        # install path shape \Blazer\Application / \Blazer\User Data. The
        # bare install folder and registry keys are handled by the exact
        # FolderNames / RegistrySubKeys lists instead.
        Name             = 'Blazer'
        ProcessPattern   = '(?i)^(new_)?blazer(?=browser|[\s\\/._-]|$)'
        MatchPattern     = '(?i)(?<![a-z])blazer[\s_-]*browser|(?<![a-z])blazer_(updater|installer)|[\\/]blazer[\\/](application|user data)|(?<![a-z])blazer\.exe$'
        # RegNamePattern matches Blazer's browser-registration key NAMES, which
        # MatchPattern deliberately doesn't (they're bare 'Blazer' + a random
        # hash): Blazer.<hash>, BlazerHTM.<hash>, BlazerPDF.<hash>, and the
        # W~Blazer.<hash> Start tile. Applied ONLY to the registration scan
        # roots (StartMenuInternet / Classes / AppUserModelId / TileProperties).
        # Anchored + hash-suffix-aware so Trailblazer / BlazeRush never match.
        RegNamePattern   = '(?i)^(w~)?blazer(htm|html|pdf)?(\.[a-z0-9]{8,})?$'
        FolderNames      = @('Blazer', 'BlazerBrowser', 'Blazer Browser')
        ProfileRootFolderNames = @()
        MachineFolders   = @()
        RegistrySubKeys  = @(
            'Software\Blazer',
            'Software\BlazerBrowser',
            'Software\Classes\BlazerHTML',
            'Software\Clients\StartMenuInternet\Blazer',
            'Software\Microsoft\Windows\CurrentVersion\App Paths\blazer.exe',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\Blazer',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\BlazerBrowser'
        )
        MachineRegistryKeys = @()
        RegisteredAppNames  = @('Blazer')
    },
    @{
        # Shift Browser (Redbrick / Shift Technologies, Inc.). Removed by
        # default like the others. Be aware: it is code-signed by the
        # same publisher as, and installs to the same paths as, a legitimate
        # paid product, so no on-disk or signature test separates an unwanted
        # bundled install from a deliberate one — removing it by default means
        # a purposely-installed Shift is removed too (an accepted trade-off
        # for a fleet-wide remover). We still never match a bare 'shift':
        # every pattern is anchored to the exact install-path shape
        # (\Shift\chromium\, \ShiftData\), the exact process names, the
        # 'Shift Technologies' publisher string, or the campaign's specific
        # installer/dropper filenames. That keeps redshift.exe, openshift,
        # ShiftN, shift-qt, and Teams 'Shifts' safe — only real Shift Browser
        # installs are touched. There is no attested product called "Shift
        # Printer"; the printer/PDF angle is just the fake-download-button
        # lure (recipes_*/pdf_*).
        Name             = 'ShiftBrowser'
        ProcessPattern   = '(?i)^(shift|shift_pwa_launcher)$'
        MatchPattern     = '(?i)[\\/]shift[\\/]chromium[\\/]|[\\/]shiftdata([\\/]|$)|(?<![a-z])shift technologies|shift-v?[0-9][0-9.]*-(production\.)?web\.exe|^recipes(_[a-z0-9]+)?\.exe$|^pdf_[a-z0-9]+\.exe$'
        # InstallerPattern is applied ONLY to .exe/.msi filenames in Downloads
        # and on the Desktop (never to process paths / tasks / registry), so it
        # can be broader: any 'Shift-...' or 'Shift_<hash>...' installer, e.g.
        # Shift-127.4.0-Production.Web.exe, shift-v127.0.0-web.exe, or
        # Shift_qf3xyw.exe. Anchored at the start, so redshift-*/ShiftN-* don't
        # match.
        InstallerPattern = '(?i)^shift[-_].+\.(exe|msi)$'
        FolderNames      = @('Shift', 'ShiftData')
        ProfileRootFolderNames = @()
        MachineFolders   = @()
        RegistrySubKeys  = @(
            'Software\Shift',
            'Software\Shift Technologies',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\Shift'
        )
        MachineRegistryKeys = @(
            'HKLM:\SOFTWARE\Shift',
            'HKLM:\SOFTWARE\Shift Technologies',
            'HKLM:\SOFTWARE\WOW6432Node\Shift Technologies'
        )
        RegisteredAppNames  = @('Shift')
        # Shift registers Software\Clients\StartMenuInternet\Shift, which the
        # install-path-anchored MatchPattern doesn't match. RegNamePattern
        # catches the bare 'Shift' (and any Shift.<hash> / W~Shift.<hash>)
        # registration key names. '^shift$' won't hit redshift/openshift/ShiftN.
        RegNamePattern   = '(?i)^(w~)?shift(\.[a-z0-9]{8,})?$'
        PostRemovalNote  = 'Shift Browser is code-signed by Shift Technologies, Inc. and shares its install paths with a legitimate paid product; if a user installed the paid Shift on purpose, this removed it too. Test on the closed system before fleet rollout.'
    },
    @{
        # ACE AI Browser (BrowseAI LLC / Sunstream Labs; TamperedChef/EvilAI
        # cluster; Malwarebytes PUP.Optional.AceBrowser). Two co-branded parts,
        # both targeted: the 'Ace' Chromium browser (%LOCALAPPDATA%\Ace\Ace\
        # Application\ace.exe, updater under \Ace\AceUpdater\) and the
        # OneLaunch-style 'AceLauncher' dock (%LOCALAPPDATA%\AceLauncher\...,
        # AceLauncherDock).
        #
        # DANGER: 'ace' collides with Microsoft.ACE.OLEDB (Access Database
        # Engine — a LIVE data provider), Acer OEM software, Microsoft Surface,
        # ACEStream (ace_engine.exe), WinAce, AceReader (ace.exe), and 'ace'
        # inside interface / namespace / workspace / face / trace. So NOTHING
        # here matches a bare 'ace', a leading '^ace' prefix, or a substring:
        # every pattern is anchored to the \Ace\Ace\ or \AceLauncher install
        # path, the 'ace...browser' / 'acelauncher' / 'acewebextension'
        # compounds, or exact key/process names. ace.exe (also AceReader Pro)
        # is only killed via its \Ace\Ace\Application\ path, never by name.
        #
        # MEDIUM confidence: the AceLauncher artifacts and \Ace\Ace\ structure
        # are attested; the browser's StartMenuInternet/ProgID/task names are
        # INFERRED from the family. Validate with a RegShot capture before
        # fleet use — treat inferred bits as "may miss", never "may over-match".
        Name             = 'AceAIBrowser'
        ProcessPattern   = '(?i)^(acelauncher|acelauncherupdater|acelauncherinstaller|ace_web_extension)$'
        MatchPattern     = '(?i)[\\/]ace[\\/]ace[\\/]|[\\/]aceupdater[\\/]|(?<![a-z])acelauncher|(?<![a-z])ace_?web_?extension|(?<![a-z])ace[\s_-]*(ai[\s_-]*)?browser|com\.acelauncher|ace[\s_-]*browser[\s_-]*shield|(?<![a-z])acesetup\.exe'
        # InstallerPattern (Downloads/Desktop .exe/.msi names only): AceSetup.exe,
        # AceLauncherInstaller.exe, and the <lure>_AceLauncher.exe droppers.
        InstallerPattern = '(?i)^(acesetup|acelauncher.*|.+_acelauncher|ace[\s_-]*(ai[\s_-]*)?browser.*)\.(exe|msi)$'
        FolderNames      = @('AceLauncher', 'AceLauncherDock', 'AceLauncherAutoUpdate', 'AceWebExtension')
        # The browser folder is the generic 'Ace'; remove it only when the
        # nested browser exe is actually inside (guarded), so a legit
        # %LOCALAPPDATA%\Ace is never deleted blind.
        GuardedFolders   = @(@{ Path = 'Ace'; Marker = 'Ace\Application\ace.exe' })
        ProfileRootFolderNames = @()
        MachineFolders   = @()
        RegistrySubKeys  = @(
            'Software\AceLauncher',
            'Software\AceLauncherUpdater',
            'Software\AceUpdater',
            'Software\Microsoft\Windows\CurrentVersion\Uninstall\AceLauncher'
        )
        MachineRegistryKeys = @()
        RegisteredAppNames  = @('Ace', 'AceLauncher')
        # Browser registration key NAMES (StartMenuInternet\Ace.<hash>, Classes
        # AceHTM.<hash>/AcePDF.<hash>, W~Ace.<hash> tile) that MatchPattern
        # misses. Requires 'htm'/'pdf' OR a .<hash> suffix, so it can never hit
        # Acer, ACEStream, AceText, or Microsoft.ACE.OLEDB.
        RegNamePattern   = '(?i)^(w~)?ace(htm|pdf)(\.[a-z0-9]{8,})?$|^(w~)?ace\.[a-z0-9]{8,}$'
        PostRemovalNote  = 'ACE AI Browser coverage is partly inferred from the PUP family — validate removal with a RegShot capture on the closed test system before fleet rollout. It exfiltrates browser history/cookies; treat an infection as more than cosmetic adware.'
    }
)

# All target names, in definition order. Front-ends use this for menus.
$script:PupNames = @($script:PupDefinitions | ForEach-Object { $_.Name })

# ---------------------------------------------------------------------------
# Get-PUPContext — resolve elevation, profile dirs, and registry hives once.
# ---------------------------------------------------------------------------
function Get-PUPContext {
    $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
               ).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

    # Profile folders to sweep for files/shortcuts.
    $profileDirs = @(
        if ($isAdmin) {
            Get-ChildItem -Path (Join-Path $env:SystemDrive 'Users') -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notin @('Public', 'Default', 'Default User', 'All Users') } |
                Select-Object -ExpandProperty FullName
        }
        else {
            $env:USERPROFILE
        }
    ) | Where-Object { $_ }

    # HKCU always; when elevated, every loaded user hive under HKEY_USERS
    # (skipping the current SID so we don't sweep it twice). Hives of
    # logged-off users aren't loaded and are not touched.
    $currentSid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $userHives  = @('HKCU:')
    if ($isAdmin) {
        $userHives += Get-ChildItem -Path 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue |
            Where-Object { $_.PSChildName -like 'S-1-5-21-*' -and
                           $_.PSChildName -notlike '*_Classes' -and
                           $_.PSChildName -ne $currentSid } |
            ForEach-Object { "Registry::HKEY_USERS\$($_.PSChildName)" }
    }

    [PSCustomObject]@{
        IsAdmin     = $isAdmin
        ProfileDirs = @($profileDirs)
        UserHives   = @($userHives)
    }
}

# ---------------------------------------------------------------------------
# New-PUPFinding — build one detection record. Phase controls removal order:
#   1 = process (killed first), 2 = scheduled task, 3 = files/registry/etc.
# RemoveAction is a closure that performs the removal and throws on failure;
# it is NOT executed during scanning.
# ---------------------------------------------------------------------------
function New-PUPFinding {
    param(
        [string]$PUP,
        [string]$Category,
        [string]$Item,
        [int]$Phase,
        [scriptblock]$RemoveAction
    )
    [PSCustomObject]@{
        PUP          = $PUP
        Category     = $Category
        Item         = $Item
        Status       = 'Detected'
        Detail       = ''
        Phase        = $Phase
        RemoveAction = $RemoveAction
    }
}

# Normalize a registry path to a comparable identity so the same key found by
# two different sweeps (the vendor-key list uses an 'HKCU:\...' drive path; the
# uninstall/registration scans use a provider PSPath) de-dupes to one finding.
function ConvertTo-CanonicalRegPath {
    param([string]$Path)
    $p = $Path -replace '(?i)^Microsoft\.PowerShell\.Core\\Registry::', ''
    $p = $p -replace '(?i)^Registry::', ''
    $p = $p -replace '(?i)^HKEY_CURRENT_USER', 'HKCU:'
    $p = $p -replace '(?i)^HKEY_LOCAL_MACHINE', 'HKLM:'
    $p = $p -replace '(?i)^HKEY_USERS', 'HKU:'
    $p = $p -replace '(?i)^HKEY_CLASSES_ROOT', 'HKCR:'
    return $p.TrimEnd('\').ToLowerInvariant()
}

# ---------------------------------------------------------------------------
# Invoke-PUPScan — detect (never remove). Returns an array of findings, each
# carrying a RemoveAction closure that Invoke-PUPRemoval can later execute.
# ---------------------------------------------------------------------------
function Invoke-PUPScan {
    [CmdletBinding()]
    param(
        [ValidateSet('WaveBrowser', 'Blazer', 'ShiftBrowser', 'AceAIBrowser')]
        [string[]]$Target = @('WaveBrowser', 'Blazer', 'ShiftBrowser', 'AceAIBrowser')
    )

    $ctx         = Get-PUPContext
    $isAdmin     = $ctx.IsAdmin
    $profileDirs = $ctx.ProfileDirs
    $userHives   = $ctx.UserHives
    if (-not $isAdmin) {
        Write-Warning 'Not elevated — scanning the current user profile only. Run as admin/SYSTEM to cover all profiles.'
    }

    $activePups = @($script:PupDefinitions | Where-Object { $_.Name -in $Target })
    $findings   = New-Object System.Collections.Generic.List[object]
    # Tracks registry keys already queued for removal so one key caught by both
    # the vendor-key list and the uninstall/registration scans is listed once.
    $seenReg    = New-Object 'System.Collections.Generic.HashSet[string]'

    # --- 1. Processes (by name or executable path) ---
    $allProcs = @(Get-Process -ErrorAction SilentlyContinue | Select-Object Id, Name, Path)
    foreach ($pup in $activePups) {
        foreach ($p in @($allProcs | Where-Object {
                    $_.Name -match $pup.ProcessPattern -or ($_.Path -and $_.Path -match $pup.MatchPattern) })) {
            $procId = $p.Id
            $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Process' -Phase 1 `
                -Item ("{0} (PID {1}) {2}" -f $p.Name, $p.Id, $p.Path) `
                -RemoveAction { Stop-Process -Id $procId -Force -ErrorAction Stop }.GetNewClosure()))
        }
    }

    # --- 1b. Windows services whose binary IMAGE PATH is under a PUP install
    #     folder (e.g. ACE's machine-scope 'AceUpdater' Google-Update-style
    #     service). Matched on the service's binary path, NEVER its name, so a
    #     legit service can't match — its binary isn't under a PUP folder.
    #     Stopped + deleted (Phase 2) before file removal. Needs admin; on a
    #     non-Windows host Win32_Service is absent and this yields nothing.
    foreach ($svc in @(Get-CimInstance -ClassName Win32_Service -ErrorAction SilentlyContinue)) {
        $svcPath = [string]$svc.PathName
        if (-not $svcPath) { continue }
        foreach ($pup in $activePups) {
            if ($svcPath -match $pup.MatchPattern) {
                $svcName = $svc.Name
                $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Service' -Phase 2 `
                    -Item ("{0}  ({1})" -f $svcName, $svcPath) `
                    -RemoveAction {
                        Stop-Service -Name $svcName -Force -ErrorAction SilentlyContinue
                        $out = & sc.exe delete $svcName 2>&1
                        # 1060 = service does not exist -> already gone, not a failure
                        if ($LASTEXITCODE -ne 0 -and "$out" -notmatch '1060') { throw "sc delete $svcName failed: $out" }
                    }.GetNewClosure()))
                break
            }
        }
    }

    # --- 2. Scheduled tasks (name / path / action-executable, blob-joined) ---
    if (Get-Command Get-ScheduledTask -ErrorAction SilentlyContinue) {
        $allTasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue | ForEach-Object {
            $actStr = ($_.Actions | ForEach-Object { $_.Execute }) -join ' | '
            [PSCustomObject]@{ Task = $_; Blob = "$($_.TaskName) | $($_.TaskPath) | $actStr" }
        })
        foreach ($pup in $activePups) {
            foreach ($t in @($allTasks | Where-Object { $_.Blob -match $pup.MatchPattern })) {
                $taskName = $t.Task.TaskName
                $taskPath = $t.Task.TaskPath
                $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'ScheduledTask' -Phase 2 `
                    -Item "$taskPath$taskName" `
                    -RemoveAction { Unregister-ScheduledTask -TaskName $taskName -TaskPath $taskPath -Confirm:$false -ErrorAction Stop }.GetNewClosure()))
            }
        }
    }
    else {
        Write-Warning 'ScheduledTasks module unavailable — task sweep skipped. WaveBrowser reinstalls via its tasks; remove them with schtasks.exe manually.'
    }

    # --- 3. Install folders (exact names under known roots) ---
    foreach ($userDir in $profileDirs) {
        $appDataRoots = @(
            (Join-Path $userDir 'AppData\Local'),
            (Join-Path $userDir 'AppData\Roaming'),
            (Join-Path $userDir 'AppData\Local\Programs')
        )
        foreach ($pup in $activePups) {
            $candidates = @(
                foreach ($root in $appDataRoots) {
                    foreach ($folder in $pup.FolderNames) { Join-Path $root $folder }
                }
                foreach ($folder in $pup.ProfileRootFolderNames) { Join-Path $userDir $folder }
            )
            foreach ($path in @($candidates | Where-Object { Test-Path -LiteralPath $_ })) {
                $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Folder' -Phase 3 -Item $path `
                    -RemoveAction { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
            }
            # Guarded folders: a generically-named folder under AppData\Local is
            # removed only when the PUP's marker (a file, possibly nested) is
            # actually inside it — e.g. Ace's %LOCALAPPDATA%\Ace is removed only
            # when Ace\Application\ace.exe exists under it, so a legit same-named
            # folder is never deleted blind. Marker may be a nested relative
            # path and may contain wildcards (hence Test-Path -Path, not -Literal).
            foreach ($guard in @($pup.GuardedFolders)) {
                if (-not $guard) { continue }
                $path = Join-Path (Join-Path $userDir 'AppData\Local') $guard.Path
                if ((Test-Path -LiteralPath $path) -and (Test-Path -Path (Join-Path $path $guard.Marker))) {
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Folder' -Phase 3 -Item $path `
                        -RemoveAction { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
        }
    }
    # Machine-wide folders (rare). '^\\' drops drive-relative paths produced
    # when an env var like ProgramFiles(x86) is empty on 32-bit Windows.
    foreach ($pup in $activePups) {
        foreach ($path in @($pup.MachineFolders | Where-Object { $_ -and $_ -notmatch '^\\' -and (Test-Path -LiteralPath $_) })) {
            $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Folder' -Phase 3 -Item $path `
                -RemoveAction { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
        }
    }

    # --- 4. Leftover installers / dropped exes in Downloads and Desktop ---
    foreach ($userDir in $profileDirs) {
        foreach ($dirName in @('Downloads', 'Desktop')) {
            $dir = Join-Path $userDir $dirName
            if (-not (Test-Path -LiteralPath $dir)) { continue }
            $installers = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension -in @('.exe', '.msi') })
            foreach ($pup in $activePups) {
                foreach ($f in @($installers | Where-Object {
                            $_.Name -match $pup.MatchPattern -or
                            ($pup.InstallerPattern -and $_.Name -match $pup.InstallerPattern) })) {
                    $filePath = $f.FullName
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Installer' -Phase 3 -Item $filePath `
                        -RemoveAction { Remove-Item -LiteralPath $filePath -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
        }
    }

    # --- 5. Registry ---
    foreach ($pup in $activePups) {

        # 5a. Known vendor/uninstall keys in each user hive, plus HKLM keys.
        $vendorKeys = @(
            foreach ($hive in $userHives) {
                foreach ($subKey in $pup.RegistrySubKeys) { Join-Path $hive $subKey }
            }
            $pup.MachineRegistryKeys
        )
        foreach ($keyPath in @($vendorKeys | Where-Object { $_ -and (Test-Path -LiteralPath $_) })) {
            if (-not $seenReg.Add((ConvertTo-CanonicalRegPath $keyPath))) { continue }
            $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'RegistryKey' -Phase 3 -Item $keyPath `
                -RemoveAction { Remove-Item -LiteralPath $keyPath -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
        }

        # 5b. Run/RunOnce values (user hives + HKLM) whose name or data matches.
        $runKeys = @(
            foreach ($hive in $userHives) {
                Join-Path $hive 'Software\Microsoft\Windows\CurrentVersion\Run'
                Join-Path $hive 'Software\Microsoft\Windows\CurrentVersion\RunOnce'
            }
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
            'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
        )
        foreach ($runKey in $runKeys) {
            $key = Get-Item -LiteralPath $runKey -ErrorAction SilentlyContinue
            if (-not $key) { continue }
            foreach ($valueName in $key.GetValueNames()) {
                $valueData = $key.GetValue($valueName)
                if ("$valueName | $valueData" -match $pup.MatchPattern) {
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'RunValue' -Phase 3 `
                        -Item "$runKey : $valueName = $valueData" `
                        -RemoveAction { Remove-ItemProperty -LiteralPath $runKey `
                            -Name ([Management.Automation.WildcardPattern]::Escape($valueName)) -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
        }

        # 5c. Uninstall entries whose keyname/DisplayName/Publisher/location match.
        $uninstallRoots = @(
            foreach ($hive in $userHives) {
                Join-Path $hive 'Software\Microsoft\Windows\CurrentVersion\Uninstall'
            }
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'
            'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
        )
        foreach ($root in $uninstallRoots) {
            foreach ($entry in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
                $props = Get-ItemProperty -LiteralPath $entry.PSPath -ErrorAction SilentlyContinue
                $blob = @($entry.PSChildName, $props.DisplayName, $props.Publisher, $props.InstallLocation) -join ' | '
                if ($blob -match $pup.MatchPattern) {
                    $entryPath = $entry.PSPath
                    if (-not $seenReg.Add((ConvertTo-CanonicalRegPath $entryPath))) { continue }
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'UninstallEntry' -Phase 3 `
                        -Item ("{0} ({1})" -f $entry.PSChildName, $props.DisplayName) `
                        -RemoveAction { Remove-Item -LiteralPath $entryPath -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
        }

        # 5d. Browser registration + leftover ProgId/COM classes. These are
        #     often bare-named or hash-suffixed (Blazer.<hash>, BlazerHTM.<hash>,
        #     StartMenuInternet\Shift, W~<PUP>.<hash> Start tiles), so a child
        #     name matches on MatchPattern OR the PUP's RegNamePattern. HKLM
        #     added when elevated. Scan roots cover the registration/handler
        #     spots each PUP touches. Tracing / ShimInclusionList mop up the
        #     benign per-exe leftovers the installers create.
        $regScanRoots = @(
            'Software\Clients\StartMenuInternet',
            'Software\Classes',
            'Software\Classes\AppUserModelId',
            'Software\Microsoft\Windows\CurrentVersion\Start\TileProperties',
            'Software\Microsoft\Tracing',
            'Software\Microsoft\MediaPlayer\ShimInclusionList'
        )
        $regHives = @($userHives)
        if ($isAdmin) { $regHives += 'HKLM:' }
        foreach ($hive in $regHives) {
            foreach ($scanRoot in $regScanRoots) {
                $rootPath = Join-Path $hive $scanRoot
                foreach ($sub in @(Get-ChildItem -LiteralPath $rootPath -ErrorAction SilentlyContinue |
                                   Where-Object { $_.PSChildName -match $pup.MatchPattern -or
                                                  ($pup.RegNamePattern -and $_.PSChildName -match $pup.RegNamePattern) })) {
                    $subPath = $sub.PSPath
                    if (-not $seenReg.Add((ConvertTo-CanonicalRegPath $subPath))) { continue }
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'RegistryKey' -Phase 3 `
                        -Item ($subPath -replace '^.*::', '') `
                        -RemoveAction { Remove-Item -LiteralPath $subPath -Recurse -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
            $regAppsPath = Join-Path $hive 'Software\RegisteredApplications'
            $regApps = Get-Item -LiteralPath $regAppsPath -ErrorAction SilentlyContinue
            if ($regApps) {
                foreach ($valueName in @($regApps.GetValueNames() |
                         Where-Object { $_ -match $pup.MatchPattern -or $_ -in @($pup.RegisteredAppNames) })) {
                    $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'RegistryValue' -Phase 3 `
                        -Item "$regAppsPath : $valueName" `
                        -RemoveAction { Remove-ItemProperty -LiteralPath $regAppsPath `
                            -Name ([Management.Automation.WildcardPattern]::Escape($valueName)) -Force -ErrorAction Stop }.GetNewClosure()))
                }
            }
        }
    }

    # --- 5e. MSIX/Store packages ---
    # Remove-AppxPackage is the ONLY capability in this tool that can actually
    # UNINSTALL an installed app, so it is deliberately conservative:
    #   * it acts ONLY on packages whose Name matches a PUP's explicit
    #     AppxPattern. No PUP defines one today (the reported 'Blazer Browser'
    #     Store listing was never confirmed to a package identity), so this
    #     block is a no-op — it cannot uninstall anything until a confirmed
    #     package name is added; and
    #   * even then it hard-excludes Microsoft / first-party / OS / framework
    #     packages, so browsers such as Microsoft Edge and any Store/system
    #     app can never be removed here.
    $appxPups = @($activePups | Where-Object { $_.AppxPattern })
    if ($appxPups.Count -gt 0) {
        $firstParty = '(?i)^(microsoft|windows|microsoftwindows|nvidia|realtek|intel|dell|hp|lenovo)\.'
        $appxPackages = @(
            if ($isAdmin) { Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue }
            else          { Get-AppxPackage -ErrorAction SilentlyContinue }
        ) | Where-Object {
            $_.Name -notmatch $firstParty -and
            $_.Publisher -notmatch 'CN=Microsoft' -and
            -not $_.IsFramework -and $_.SignatureKind -ne 'System'
        }
        $removeAppxCmd = Get-Command Remove-AppxPackage -ErrorAction SilentlyContinue
        $appxAllUsers  = $isAdmin -and $removeAppxCmd -and $removeAppxCmd.Parameters.ContainsKey('AllUsers')
        foreach ($pup in $appxPups) {
            foreach ($pkg in @($appxPackages | Where-Object { $_.Name -match $pup.AppxPattern })) {
                $pkgFullName = $pkg.PackageFullName
                $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'AppxPackage' -Phase 3 -Item $pkgFullName `
                    -RemoveAction {
                        if ($appxAllUsers) { Remove-AppxPackage -Package $pkgFullName -AllUsers -ErrorAction Stop }
                        else               { Remove-AppxPackage -Package $pkgFullName -ErrorAction Stop }
                    }.GetNewClosure()))
            }
        }
    }

    # --- 6. Shortcuts (.lnk) — judged by resolved target when readable ---
    $shortcutRoots = @(
        foreach ($userDir in $profileDirs) {
            Join-Path $userDir 'Desktop'
            Join-Path $userDir 'AppData\Roaming\Microsoft\Windows\Start Menu'
            Join-Path $userDir 'AppData\Roaming\Microsoft\Internet Explorer\Quick Launch'
        }
        "$env:PUBLIC\Desktop"
        "$env:ProgramData\Microsoft\Windows\Start Menu"
    ) | Where-Object { Test-Path -LiteralPath $_ }

    # A shortcut is removed ONLY when its RESOLVED TARGET points at a PUP path
    # (e.g. into \Wavesor Software\ or \Shift\chromium\). We never delete a
    # shortcut on a name match alone — matching by name is what let the tool
    # touch shortcuts it didn't own. If the target can't be resolved, the
    # shortcut is left in place (a dead PUP link is harmless once the real
    # files/tasks/registry are gone).
    #
    # NOTE: this local MUST NOT be named $target — that aliases the
    # [string[]]$Target parameter (PowerShell variable names are
    # case-insensitive), and on Windows PowerShell 5.1 the type-constrained
    # reassignment leaves it holding the PUP-name array, so EVERY shortcut
    # would "match". Use a distinct name.
    $wsShell = $null
    try { $wsShell = New-Object -ComObject WScript.Shell } catch { }
    foreach ($root in $shortcutRoots) {
        $links = @(Get-ChildItem -LiteralPath $root -Filter '*.lnk' -Recurse -Force -ErrorAction SilentlyContinue)
        foreach ($pup in $activePups) {
            foreach ($lnk in $links) {
                $lnkTarget = ''
                if ($wsShell) {
                    try { $lnkTarget = [string]$wsShell.CreateShortcut($lnk.FullName).TargetPath } catch { }
                }
                if (-not ($lnkTarget -and ($lnkTarget -match $pup.MatchPattern))) { continue }
                $lnkPath = $lnk.FullName
                $findings.Add((New-PUPFinding -PUP $pup.Name -Category 'Shortcut' -Phase 3 `
                    -Item "$lnkPath -> $lnkTarget" `
                    -RemoveAction { Remove-Item -LiteralPath $lnkPath -Force -ErrorAction Stop }.GetNewClosure()))
            }
        }
    }

    return $findings.ToArray()
}

# ---------------------------------------------------------------------------
# Invoke-PUPRemoval — execute the RemoveAction of each supplied finding, in
# phase order (processes first, then tasks, then files/registry). After the
# process kills, pause briefly so file locks release before deletion. Sets
# each finding's Status to 'Removed' or 'Failed' (with Detail) in place.
# ---------------------------------------------------------------------------
function Invoke-PUPRemoval {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [object[]]$Finding
    )

    $ordered   = @($Finding | Sort-Object Phase)
    $settled   = $false
    foreach ($f in $ordered) {
        if (-not $settled -and $f.Phase -ge 3) {
            # Pause before touching files if we killed a process or stopped a
            # service/task (phase 1-2), so their file locks release first.
            if (@($Finding | Where-Object { $_.Phase -lt 3 -and $_.Status -eq 'Removed' }).Count -gt 0) {
                Start-Sleep -Seconds 2
            }
            $settled = $true
        }
        try {
            & $f.RemoveAction
            $f.Status = 'Removed'
            $f.Detail = ''
        }
        catch {
            # "Already gone" is success, not failure — a second finding for the
            # same key (e.g. the vendor-key list and the uninstall-entry scan
            # both catch one Uninstall\<PUP> key), a parent removal that took a
            # child with it, or a process that exited before we killed it. Only
            # genuine errors (locked file, access denied) count as failures.
            if ($_.CategoryInfo.Category -eq 'ObjectNotFound') {
                $f.Status = 'Removed'
                $f.Detail = '(already gone)'
            }
            else {
                $f.Status = 'Failed'
                $f.Detail = $_.Exception.Message
            }
        }
    }
    return $Finding
}

# ---------------------------------------------------------------------------
# Reporting helpers
# ---------------------------------------------------------------------------

# Console display grouped by PUP -> Category, colour-coded by Status.
function Write-PUPFindings {
    param(
        [object[]]$Finding,
        [string]$Title
    )
    if ($Title) { Write-Host "`n=== $Title ===" -ForegroundColor Cyan }
    if (@($Finding).Count -eq 0) {
        Write-Host '  (nothing)' -ForegroundColor DarkGray
        return
    }
    foreach ($pupGroup in ($Finding | Group-Object PUP | Sort-Object Name)) {
        Write-Host ("`n  {0}  ({1} artifact(s))" -f $pupGroup.Name, $pupGroup.Count) -ForegroundColor White
        foreach ($f in ($pupGroup.Group | Sort-Object Phase, Category)) {
            $color = switch ($f.Status) {
                'Removed'  { 'Green' }
                'Detected' { 'Yellow' }
                'Failed'   { 'Red' }
                default    { 'Gray' }
            }
            Write-Host ("    [{0,-8}] {1,-14} {2}" -f $f.Status, $f.Category, $f.Item) -ForegroundColor $color
            if ($f.Status -eq 'Failed' -and $f.Detail) {
                Write-Host ("                 -> $($f.Detail)") -ForegroundColor DarkRed
            }
        }
    }
}

# Per-PUP follow-up guidance for PUPs that were actually found.
function Get-PUPPostRemovalNotes {
    param([object[]]$Finding)
    $foundPups = @($Finding | Select-Object -ExpandProperty PUP -Unique)
    foreach ($def in $script:PupDefinitions) {
        if ($def.PostRemovalNote -and $def.Name -in $foundPups) { $def.PostRemovalNote }
    }
}

# Write a timestamped CSV + text log. Returns the file paths written.
# -Directory is a preferred output folder (e.g. the interactive tester passes
# the current user's Downloads); it is tried first, then the machine defaults.
function Export-PUPReport {
    param(
        [object[]]$Finding,
        [string]$Stamp,      # caller supplies a timestamp string (e.g. yyyyMMdd_HHmmss)
        [string]$Directory   # optional preferred output folder, tried first
    )
    if (-not $Stamp) { $Stamp = (Get-Date -Format 'yyyyMMdd_HHmmss') }
    $candidates = @()
    if ($Directory) { $candidates += $Directory }
    $candidates += @("$env:ProgramData\PUPRemover\Logs", "$env:TEMP\PUPRemover", (Join-Path (Get-Location) 'PUPRemover-logs'))
    $logDir = $null
    foreach ($c in $candidates) {
        if (-not $c) { continue }
        try { New-Item -ItemType Directory -Path $c -Force -ErrorAction Stop | Out-Null; $logDir = $c; break } catch { }
    }
    if (-not $logDir) { return @() }

    $csv = Join-Path $logDir "PUPRemover_$Stamp.csv"
    $log = Join-Path $logDir "PUPRemover_$Stamp.log"
    $written = @()
    try {
        @($Finding) | Select-Object PUP, Category, Status, Item, Detail |
            Export-Csv -LiteralPath $csv -NoTypeInformation -ErrorAction Stop
        $written += $csv
    } catch { }
    try {
        $lines = foreach ($f in @($Finding | Sort-Object PUP, Phase, Category)) {
            "{0}`t{1}`t{2}`t{3}`t{4}" -f $f.Status, $f.PUP, $f.Category, $f.Item, $f.Detail
        }
        Set-Content -LiteralPath $log -Value $lines -Encoding UTF8 -ErrorAction Stop
        $written += $log
    } catch { }
    return $written
}

# ===========================================================================
# S1 auto driver (appended after PUPCore by build.ps1).
#
# SentinelOne runs this as SYSTEM, non-interactively. It scans, reports what
# it found (paths, registry keys, tasks, ...), removes everything, reports the
# per-item result, writes a CSV+log, and exits with a machine-readable code:
#   0 = clean, or everything removed successfully
#   2 = one or more removals failed (reboot the endpoint and re-run)
# Deploy via:  powershell.exe -ExecutionPolicy Bypass -File PUPRemover-S1.ps1
# ===========================================================================

# This is a fleet-wide remover: all targeted PUPs are removed unconditionally.
# NOTE on Shift Browser — it is code-signed by the same publisher as, and
# installs to the same paths as, a legitimate paid product, so including it
# here means a deliberately-installed Shift is also removed. That is the
# intended behaviour for this tool. Matching is still install-path-anchored,
# so unrelated software (redshift / openshift / ShiftN / Teams Shifts) is
# never touched — only actual Shift Browser installs.
$stamp   = Get-Date -Format 'yyyyMMdd_HHmmss'
$targets = @('WaveBrowser', 'Blazer', 'ShiftBrowser', 'AceAIBrowser')

Write-Host "PUPRemover — SentinelOne auto mode"
Write-Host ("Run: {0}   Targets: {1}" -f $stamp, ($targets -join ', '))

$findings = @(Invoke-PUPScan -Target $targets)

if ($findings.Count -eq 0) {
    Write-Host "`nClean — no PUP artifacts found." -ForegroundColor Green
    exit 0
}

Write-PUPFindings -Finding $findings -Title 'ARTIFACTS FOUND'

Write-Host "`n=== REMOVING ===" -ForegroundColor Cyan
Invoke-PUPRemoval -Finding $findings | Out-Null
Write-PUPFindings -Finding $findings -Title 'REMOVAL RESULT'

foreach ($note in (Get-PUPPostRemovalNotes -Finding $findings)) { Write-Warning $note }

$report = Export-PUPReport -Finding $findings -Stamp $stamp
if ($report.Count -gt 0) { Write-Host ("`nReport written: {0}" -f ($report -join '  ;  ')) }

$removed = @($findings | Where-Object { $_.Status -eq 'Removed' }).Count
$failed  = @($findings | Where-Object { $_.Status -eq 'Failed' }).Count
Write-Host ("`nSummary: {0} found, {1} removed, {2} failed." -f $findings.Count, $removed, $failed)

if ($failed -gt 0) {
    Write-Warning "$failed removal(s) failed — a reboot may release locked files. Reboot the endpoint and re-run."
    exit 2
}
exit 0

